// Firebase access for the Mac app: sign-in (via the web app's /link page),
// writing notes to Firestore over REST, an offline queue, and a one-time
// import of notes from the old local database.

import AppKit
import AuthenticationServices
import SQLite3

// CloudConfig (project keys and URLs) lives in Config.swift, generated by scripts/configure.py.

struct Session: Codable {
    var refreshToken: String
    var uid: String
    var email: String
    var name: String
}

/// A note waiting to be uploaded. The id doubles as the Firestore document id, so retries never duplicate.
struct PendingNote: Codable {
    var id: String
    var content: String
    var noteDate: String
    var createdAt: String
    var shot: PendingShot? = nil
}

/// A screenshot waiting to upload; the full JPEG sits in pending-shots/<id>.jpg until it's sent.
struct PendingShot: Codable {
    var id: String
    var width: Int
    var height: Int
    var thumb: String // base64 JPEG
}

enum SaveResult {
    case synced
    case queued(String)
}

private func isoTimestamp(_ date: Date = Date()) -> String {
    let f = ISO8601DateFormatter()
    f.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
    return f.string(from: date)
}

/// Firestore REST value encoding.
private func fsValue(_ value: Any?) -> [String: Any] {
    guard let value else { return ["nullValue": NSNull()] }
    switch value {
    case let s as String: return ["stringValue": s]
    case let b as Bool: return ["booleanValue": b]
    case let i as Int: return ["integerValue": String(i)]
    case let d as Double: return ["doubleValue": d]
    case let a as [String]: return ["arrayValue": a.isEmpty ? [:] : ["values": a.map { ["stringValue": $0] }]]
    case let a as [[String: Any?]]: return ["arrayValue": a.isEmpty ? [:] : ["values": a.map { fsValue($0) }]]
    case let m as [String: Any?]: return ["mapValue": ["fields": m.mapValues { fsValue($0) }]]
    default: return ["nullValue": NSNull()]
    }
}

/// Firestore REST value → plain Swift value (strings, numbers, nil, arrays, maps).
private func fsDecode(_ v: [String: Any]) -> Any? {
    if let s = v["stringValue"] as? String { return s }
    if let i = v["integerValue"] as? String { return Int(i) }
    if let d = v["doubleValue"] as? Double { return d }
    if let b = v["booleanValue"] as? Bool { return b }
    if let a = (v["arrayValue"] as? [String: Any]) { return (a["values"] as? [[String: Any]] ?? []).map { fsDecode($0) } }
    if let m = (v["mapValue"] as? [String: Any])?["fields"] as? [String: [String: Any]] { return m.mapValues { fsDecode($0) } }
    return nil
}

/// A note as the Mac app needs it for reminders.
struct NoteInfo {
    let id: String
    let content: String
    let noteDate: String
    let status: String
    let createdAt: String?
    let completedAt: String?
    let originalDate: String?
    let timesMoved: Int
}

/// Same rules as web/notes-model.js: "- item", "[ ] item", "[x] item" lines become a checklist.
func parseChecklist(_ text: String) -> (content: String, checklist: [[String: Any?]]) {
    let pattern = #"^\s*(?:[-*•]\s*)?\[\s*([xX✓]?)\s*\]\s+(.+)$|^\s*[-*•]\s+(.+)$"#
    guard let re = try? NSRegularExpression(pattern: pattern) else { return (text, []) }
    var items: [[String: Any?]] = []
    var rest: [String] = []
    for line in text.components(separatedBy: "\n") {
        let ns = line as NSString
        if let m = re.firstMatch(in: line, range: NSRange(location: 0, length: ns.length)) {
            let r2 = m.range(at: 2), r3 = m.range(at: 3)
            let itemText = (r2.location != NSNotFound ? ns.substring(with: r2) : ns.substring(with: r3)).trimmingCharacters(in: .whitespaces)
            let done = m.range(at: 1).location != NSNotFound && m.range(at: 1).length > 0
            items.append(["id": String(UUID().uuidString.prefix(8)).lowercased(), "text": String(itemText.prefix(500)), "done": done])
        } else if !line.trimmingCharacters(in: .whitespaces).isEmpty {
            rest.append(line.trimmingCharacters(in: .whitespaces))
        }
    }
    if items.isEmpty { return (text, []) }
    return (rest.isEmpty ? "Checklist" : rest.joined(separator: "\n"), Array(items.prefix(100)))
}

final class Cloud: NSObject, ASWebAuthenticationPresentationContextProviding {
    private(set) var session: Session?
    var onSessionChange: (() -> Void)?
    weak var anchorWindow: NSWindow?

    private var idToken: String?
    private var idTokenExpiry = Date.distantPast
    private var authSession: ASWebAuthenticationSession?
    private var flushing = false

    private let dir: URL
    private var sessionFile: URL { dir.appendingPathComponent("session.json") }
    private var pendingFile: URL { dir.appendingPathComponent("pending.json") }
    private var legacyDB: URL { dir.appendingPathComponent("notes.db") }
    private var shotsDir: URL { dir.appendingPathComponent("pending-shots") }

    override init() {
        dir = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Library/Application Support/QuickNotes")
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        super.init()
        session = (try? Data(contentsOf: sessionFile)).flatMap { try? JSONDecoder().decode(Session.self, from: $0) }
    }

    var isSignedIn: Bool { session != nil }
    var pendingCount: Int { loadPending().count }

    // MARK: sign-in

    /// Opens the web app's /link page in a browser sheet; it signs in with Google and hands back a refresh token.
    func signIn(_ done: @escaping (String?) -> Void) {
        let auth = ASWebAuthenticationSession(url: CloudConfig.linkURL, callbackURLScheme: CloudConfig.callbackScheme) { [weak self] callback, error in
            DispatchQueue.main.async {
                guard let self else { return }
                self.authSession = nil
                if let error = error as? ASWebAuthenticationSessionError, error.code == .canceledLogin { return done(nil) }
                guard let callback,
                      let fragment = URLComponents(url: callback, resolvingAgainstBaseURL: false)?.fragment,
                      let token = URLComponents(string: "?" + fragment)?.queryItems?.first(where: { $0.name == "refresh_token" })?.value
                else { return done(error?.localizedDescription ?? "Sign-in didn’t return a token.") }
                self.session = Session(refreshToken: token, uid: "", email: "", name: "")
                self.idTokenExpiry = .distantPast
                self.withIdToken { result in
                    switch result {
                    case .success:
                        self.onSessionChange?()
                        self.afterSignIn()
                        done(nil)
                    case .failure(let error):
                        self.signOut()
                        done(error.message)
                    }
                }
            }
        }
        auth.presentationContextProvider = self
        auth.prefersEphemeralWebBrowserSession = false
        authSession = auth
        auth.start()
    }

    func signOut() {
        session = nil
        idToken = nil
        try? FileManager.default.removeItem(at: sessionFile)
        onSessionChange?()
    }

    func presentationAnchor(for session: ASWebAuthenticationSession) -> ASPresentationAnchor {
        anchorWindow ?? NSApp.windows.first ?? NSWindow()
    }

    private func saveSession() {
        guard let session, let data = try? JSONEncoder().encode(session) else { return }
        // token file readable only by this user, like other CLI/desktop credentials
        FileManager.default.createFile(atPath: sessionFile.path, contents: data, attributes: [.posixPermissions: 0o600])
    }

    private func afterSignIn() {
        recordUser()
        importLegacyNotes { [weak self] in self?.flushPending() }
    }

    /// Exchanges the refresh token for a short-lived ID token (cached until it nearly expires).
    private func withIdToken(_ done: @escaping (Result<String, CloudError>) -> Void) {
        guard let current = session else { return done(.failure(.notSignedIn)) }
        if let idToken, idTokenExpiry > Date().addingTimeInterval(60) { return done(.success(idToken)) }

        var req = URLRequest(url: URL(string: "https://securetoken.googleapis.com/v1/token?key=\(CloudConfig.apiKey)")!)
        req.httpMethod = "POST"
        req.timeoutInterval = 10
        req.setValue("application/x-www-form-urlencoded", forHTTPHeaderField: "Content-Type")
        let token = current.refreshToken.addingPercentEncoding(withAllowedCharacters: .alphanumerics) ?? ""
        req.httpBody = "grant_type=refresh_token&refresh_token=\(token)".data(using: .utf8)
        URLSession.shared.dataTask(with: req) { data, resp, err in
            let status = (resp as? HTTPURLResponse)?.statusCode ?? 0
            let body = data.flatMap { try? JSONSerialization.jsonObject(with: $0) as? [String: Any] }
            DispatchQueue.main.async {
                guard status == 200, let body, let id = body["id_token"] as? String else {
                    if (400..<500).contains(status) {
                        // refresh token revoked or expired: needs a fresh sign-in
                        self.signOut()
                        return done(.failure(.notSignedIn))
                    }
                    return done(.failure(.network(err?.localizedDescription ?? "HTTP \(status)")))
                }
                let claims = Cloud.claims(of: id)
                self.idToken = id
                self.idTokenExpiry = Date().addingTimeInterval(Double(body["expires_in"] as? String ?? "3600") ?? 3600)
                self.session = Session(refreshToken: body["refresh_token"] as? String ?? current.refreshToken,
                                       uid: body["user_id"] as? String ?? current.uid,
                                       email: (claims["email"] as? String ?? current.email).lowercased(),
                                       name: claims["name"] as? String ?? current.name)
                self.saveSession()
                done(.success(id))
            }
        }.resume()
    }

    private static func claims(of jwt: String) -> [String: Any] {
        let parts = jwt.split(separator: ".")
        guard parts.count > 1 else { return [:] }
        var b64 = parts[1].replacingOccurrences(of: "-", with: "+").replacingOccurrences(of: "_", with: "/")
        b64 += String(repeating: "=", count: (4 - b64.count % 4) % 4)
        return Data(base64Encoded: b64).flatMap { try? JSONSerialization.jsonObject(with: $0) as? [String: Any] } ?? [:]
    }

    // MARK: notes

    func saveNote(_ text: String, _ done: @escaping (SaveResult) -> Void) {
        save(PendingNote(id: UUID().uuidString, content: text, noteDate: isoDay(), createdAt: isoTimestamp()), done)
    }

    /// A screenshot note: the image goes to qn_attachments/{id}, the note carries a thumbnail and the description.
    func saveScreenshotNote(_ text: String, _ shot: Screenshot, _ done: @escaping (SaveResult) -> Void) {
        let shotId = UUID().uuidString
        try? FileManager.default.createDirectory(at: shotsDir, withIntermediateDirectories: true)
        // written first, so the screenshot survives going offline or quitting before it uploads
        try? shot.full.write(to: shotsDir.appendingPathComponent("\(shotId).jpg"), options: .atomic)
        let pending = PendingShot(id: shotId, width: shot.width, height: shot.height, thumb: shot.thumb.base64EncodedString())
        save(PendingNote(id: UUID().uuidString, content: text.isEmpty ? "Screenshot" : text,
                         noteDate: isoDay(), createdAt: isoTimestamp(), shot: pending), done)
    }

    private func save(_ note: PendingNote, _ done: @escaping (SaveResult) -> Void) {
        guard isSignedIn else {
            enqueue(note)
            return done(.queued("Saved on this Mac · sign in to sync"))
        }
        upload(note) { [weak self] error in
            guard let self else { return }
            if error == nil {
                done(.synced)
                self.flushPending()
            } else {
                self.enqueue(note)
                done(.queued(self.isSignedIn ? "Offline · will sync automatically" : "Saved on this Mac · sign in to sync"))
            }
        }
    }

    /// The user's own notes on a day (nil when unknown).
    func countNotes(on day: String, _ done: @escaping (Int?) -> Void) {
        withIdToken { result in
            guard case .success(let token) = result, let uid = self.session?.uid else { return done(nil) }
            let field = { (path: String, value: String) -> [String: Any] in
                ["fieldFilter": ["field": ["fieldPath": path], "op": "EQUAL", "value": ["stringValue": value]]]
            }
            let query: [String: Any] = ["structuredQuery": [
                "from": [["collectionId": CloudConfig.collection]],
                "where": ["compositeFilter": ["op": "AND", "filters": [field("ownerId", uid), field("note_date", day)]]],
            ]]
            self.request("POST", "documents:runQuery", token: token, body: query) { status, json in
                guard status == 200, let rows = json as? [[String: Any]] else { return done(nil) }
                // notes in Trash don't count
                done(rows.compactMap { $0["document"] as? [String: Any] }.filter { doc in
                    let fields = doc["fields"] as? [String: [String: Any]] ?? [:]
                    return fields["deleted_at"].flatMap { fsDecode($0) } == nil
                }.count)
            }
        }
    }

    /// All of the signed-in person's notes (not in Trash), for reminders and the weekly recap.
    func myNotes(_ done: @escaping ([NoteInfo]?) -> Void) {
        withIdToken { result in
            guard case .success(let token) = result, let uid = self.session?.uid else { return done(nil) }
            let query: [String: Any] = ["structuredQuery": [
                "from": [["collectionId": CloudConfig.collection]],
                "where": ["fieldFilter": ["field": ["fieldPath": "ownerId"], "op": "EQUAL", "value": ["stringValue": uid]]],
            ]]
            self.request("POST", "documents:runQuery", token: token, body: query, timeout: 20) { status, json in
                guard status == 200, let rows = json as? [[String: Any]] else { return done(nil) }
                let notes = rows.compactMap { row -> NoteInfo? in
                    guard let doc = row["document"] as? [String: Any], let name = doc["name"] as? String else { return nil }
                    let f = (doc["fields"] as? [String: [String: Any]] ?? [:]).mapValues { fsDecode($0) }
                    if f["deleted_at"].flatMap({ $0 }) != nil { return nil }
                    return NoteInfo(id: String(name.split(separator: "/").last ?? ""),
                                    content: f["content"].flatMap { $0 as? String } ?? "",
                                    noteDate: f["note_date"].flatMap { $0 as? String } ?? "",
                                    status: f["status"].flatMap { $0 as? String } ?? "open",
                                    createdAt: f["created_at"].flatMap { $0 as? String },
                                    completedAt: f["completed_at"].flatMap { $0 as? String },
                                    originalDate: f["original_date"].flatMap { $0 as? String },
                                    timesMoved: f["times_moved"].flatMap { $0 as? Int } ?? 0)
                }
                done(notes)
            }
        }
    }

    /// Moves notes to another day in one batch (same fields the web app writes).
    func move(_ notes: [NoteInfo], to day: String, _ done: @escaping (Bool) -> Void) {
        guard !notes.isEmpty else { return done(true) }
        withIdToken { result in
            guard case .success(let token) = result else { return done(false) }
            let base = "projects/\(CloudConfig.projectId)/databases/(default)/documents/\(CloudConfig.collection)/"
            let now = isoTimestamp()
            let writes: [[String: Any]] = notes.map { n in
                let fields: [String: Any?] = ["note_date": day, "original_date": n.originalDate ?? n.noteDate,
                                              "times_moved": n.timesMoved + 1, "updated_at": now]
                return ["update": ["name": base + n.id, "fields": fields.mapValues { fsValue($0) }],
                        "updateMask": ["fieldPaths": Array(fields.keys)]]
            }
            self.request("POST", "documents:commit", token: token, body: ["writes": writes]) { status, _ in done(status == 200) }
        }
    }

    /// users/{uid}.notesCreated += 1, for the users dashboard. Never affects the note itself.
    private func countNoteCreated() {
        withIdToken { result in
            guard case .success(let token) = result, let uid = self.session?.uid else { return }
            let doc = "projects/\(CloudConfig.projectId)/databases/(default)/documents/users/\(uid)"
            let body: [String: Any] = ["writes": [["transform": ["document": doc, "fieldTransforms": [
                ["fieldPath": "notesCreated", "increment": ["integerValue": "1"]],
            ]]]]]
            self.request("POST", "documents:commit", token: token, body: body) { _, _ in }
        }
    }

    private func upload(_ note: PendingNote, _ done: @escaping (String?) -> Void) {
        let parsed = parseChecklist(note.content)
        var fields: [String: Any?] = [
            "content": parsed.content, "note_date": note.noteDate, "status": "open",
            "created_at": note.createdAt, "updated_at": note.createdAt,
            "edited_at": nil, "completed_at": nil, "original_date": nil, "times_moved": 0,
            "order": Int(Date().timeIntervalSince1970 * 1000), // bottom of the day's list, same scale as the web app
        ]
        if !parsed.checklist.isEmpty { fields["checklist"] = parsed.checklist }
        guard let shot = note.shot else { return createDocument(id: note.id, fields: fields, done) }

        let file = shotsDir.appendingPathComponent("\(shot.id).jpg")
        guard let image = try? Data(contentsOf: file) else {
            // the image file is gone; still save the description
            return createDocument(id: note.id, fields: fields, done)
        }
        uploadAttachment(id: shot.id, noteId: note.id, jpeg: image, width: shot.width, height: shot.height) { error in
            if let error { return done(error) }
            fields["attachment"] = [
                "id": shot.id, "kind": "screenshot", "width": shot.width, "height": shot.height,
                "thumb": "data:image/jpeg;base64,\(shot.thumb)",
            ] as [String: Any?]
            self.createDocument(id: note.id, fields: fields) { error in
                if error == nil { try? FileManager.default.removeItem(at: file) }
                done(error)
            }
        }
    }

    /// qn_attachments/{id}: the full screenshot as base64 JPEG, readable by whoever can read its note.
    private func uploadAttachment(id: String, noteId: String, jpeg: Data, width: Int, height: Int,
                                  _ done: @escaping (String?) -> Void) {
        withIdToken { result in
            guard case .success(let token) = result, let s = self.session else { return done("Not signed in") }
            let fields: [String: Any?] = [
                "ownerId": s.uid, "noteId": noteId, "mime": "image/jpeg", "data": jpeg.base64EncodedString(),
                "width": width, "height": height, "created_at": isoTimestamp(),
            ]
            let body: [String: Any] = ["fields": fields.mapValues { fsValue($0) }]
            self.request("POST", "documents/qn_attachments?documentId=\(id)", token: token, body: body, timeout: 60) { status, json in
                if status == 200 || status == 409 { return done(nil) }
                let message = ((json as? [String: Any])?["error"] as? [String: Any])?["message"] as? String
                done(message ?? "HTTP \(status)")
            }
        }
    }

    /// Creates qn_notes/{id} owned by the signed-in user. An existing document counts as success (safe retries).
    private func createDocument(id: String, fields: [String: Any?], _ done: @escaping (String?) -> Void) {
        withIdToken { result in
            guard case .success(let token) = result, let s = self.session else { return done("Not signed in") }
            var all = fields
            all["ownerId"] = s.uid
            all["ownerEmail"] = s.email
            all["ownerName"] = s.name
            all["sharedWith"] = [String]()
            let body: [String: Any] = ["fields": all.mapValues { fsValue($0) }]
            let path = "documents/\(CloudConfig.collection)?documentId=\(id)"
            self.request("POST", path, token: token, body: body) { status, json in
                if status == 200 { self.countNoteCreated() }
                if status == 200 || status == 409 { return done(nil) }
                let message = ((json as? [String: Any])?["error"] as? [String: Any])?["message"] as? String
                done(message ?? "HTTP \(status)")
            }
        }
    }

    private func request(_ method: String, _ path: String, token: String, body: Any, timeout: TimeInterval = 10,
                         _ done: @escaping (Int, Any?) -> Void) {
        let base = "https://firestore.googleapis.com/v1/projects/\(CloudConfig.projectId)/databases/(default)/"
        var req = URLRequest(url: URL(string: base + path)!)
        req.httpMethod = method
        req.timeoutInterval = timeout
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        req.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        req.httpBody = try? JSONSerialization.data(withJSONObject: body)
        URLSession.shared.dataTask(with: req) { data, resp, _ in
            let status = (resp as? HTTPURLResponse)?.statusCode ?? 0
            let json = data.flatMap { try? JSONSerialization.jsonObject(with: $0) }
            DispatchQueue.main.async { done(status, json) }
        }.resume()
    }

    // MARK: user profile

    /// Saves who is using the Mac app to users/{uid}, touching only this app's entry under `clients`.
    func recordUser() {
        withIdToken { result in
            guard case .success(let token) = result, let s = self.session else { return }
            self.lookupAccount(token) { account in
                let now = isoTimestamp()
                let ts = { (iso: String) -> [String: Any] in ["timestampValue": iso] }
                let millis = { (key: String) -> String? in
                    (account[key] as? String).flatMap(Double.init).map { isoTimestamp(Date(timeIntervalSince1970: $0 / 1000)) }
                }
                let info = Bundle.main.infoDictionary
                var fields: [String: Any] = [
                    "uid": ["stringValue": s.uid],
                    "email": ["stringValue": s.email],
                    "displayName": ["stringValue": account["displayName"] as? String ?? s.name],
                    "photoURL": ["stringValue": account["photoUrl"] as? String ?? ""],
                    "lastSeenAt": ts(now),
                    "locale": ["stringValue": Locale.current.identifier],
                    "timeZone": ["stringValue": TimeZone.current.identifier],
                    "clients": ["mapValue": ["fields": ["mac": ["mapValue": ["fields": [
                        "lastSeenAt": ts(now),
                        "version": ["stringValue": info?["CFBundleShortVersionString"] as? String ?? ""],
                        "os": ["stringValue": ProcessInfo.processInfo.operatingSystemVersionString],
                    ]]]]]],
                ]
                if let created = millis("createdAt") { fields["createdAt"] = ts(created) }
                if let last = millis("lastLoginAt") { fields["lastSignInAt"] = ts(last) }
                if let providers = account["providerUserInfo"] as? [[String: Any]] {
                    fields["providers"] = ["arrayValue": ["values": providers.compactMap { $0["providerId"] as? String }.map { ["stringValue": $0] }]]
                }
                let mask = (fields.keys.filter { $0 != "clients" } + ["clients.mac"])
                    .map { "updateMask.fieldPaths=\($0)" }.joined(separator: "&")
                self.request("PATCH", "documents/users/\(s.uid)?\(mask)", token: token, body: ["fields": fields]) { status, json in
                    if status == 200 {
                        NSLog("QuickNotes: user profile saved")
                    } else {
                        NSLog("QuickNotes: couldn’t save user profile (HTTP \(status)) \(String(describing: json))")
                    }
                }
            }
        }
    }

    /// The account's details from Firebase Auth (sign-up date, last sign-in, providers).
    private func lookupAccount(_ token: String, _ done: @escaping ([String: Any]) -> Void) {
        var req = URLRequest(url: URL(string: "https://identitytoolkit.googleapis.com/v1/accounts:lookup?key=\(CloudConfig.apiKey)")!)
        req.httpMethod = "POST"
        req.timeoutInterval = 10
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        req.httpBody = try? JSONSerialization.data(withJSONObject: ["idToken": token])
        URLSession.shared.dataTask(with: req) { data, _, _ in
            let body = data.flatMap { try? JSONSerialization.jsonObject(with: $0) as? [String: Any] }
            let account = (body?["users"] as? [[String: Any]])?.first ?? [:]
            DispatchQueue.main.async { done(account) }
        }.resume()
    }

    // MARK: offline queue

    private func loadPending() -> [PendingNote] {
        (try? Data(contentsOf: pendingFile)).flatMap { try? JSONDecoder().decode([PendingNote].self, from: $0) } ?? []
    }

    private func storePending(_ notes: [PendingNote]) {
        if notes.isEmpty { try? FileManager.default.removeItem(at: pendingFile); return }
        if let data = try? JSONEncoder().encode(notes) { try? data.write(to: pendingFile, options: .atomic) }
    }

    private func enqueue(_ note: PendingNote) {
        var all = loadPending()
        if !all.contains(where: { $0.id == note.id }) { all.append(note) }
        storePending(all)
    }

    /// Uploads queued notes one by one; stops at the first failure and tries again next time.
    func flushPending() {
        guard isSignedIn, !flushing, let next = loadPending().first else { return }
        flushing = true
        upload(next) { [weak self] error in
            guard let self else { return }
            self.flushing = false
            guard error == nil else { return }
            self.storePending(self.loadPending().filter { $0.id != next.id })
            self.flushPending()
        }
    }

    // MARK: one-time import from the old local database

    private struct LegacyRow {
        let id: Int
        let fields: [String: Any?]
    }

    private func readLegacyRows() -> [LegacyRow]? {
        guard FileManager.default.fileExists(atPath: legacyDB.path) else { return nil }
        var db: OpaquePointer?
        guard sqlite3_open_v2(legacyDB.path, &db, SQLITE_OPEN_READONLY, nil) == SQLITE_OK else { return nil }
        defer { sqlite3_close(db) }
        var stmt: OpaquePointer?
        let sql = """
            SELECT id, content, note_date, status, created_at, updated_at, edited_at,
                   completed_at, original_date, times_moved FROM notes ORDER BY id
            """
        guard sqlite3_prepare_v2(db, sql, -1, &stmt, nil) == SQLITE_OK else { return nil }
        defer { sqlite3_finalize(stmt) }
        func text(_ i: Int32) -> String? {
            sqlite3_column_type(stmt, i) == SQLITE_NULL ? nil : String(cString: sqlite3_column_text(stmt, i))
        }
        var rows: [LegacyRow] = []
        while sqlite3_step(stmt) == SQLITE_ROW {
            rows.append(LegacyRow(id: Int(sqlite3_column_int64(stmt, 0)), fields: [
                "content": text(1), "note_date": text(2), "status": text(3),
                "created_at": text(4), "updated_at": text(5), "edited_at": text(6),
                "completed_at": text(7), "original_date": text(8), "times_moved": Int(sqlite3_column_int64(stmt, 9)),
            ]))
        }
        return rows
    }

    /// Copies notes from the pre-cloud SQLite database into Firestore, then renames the file so it runs once.
    func importLegacyNotes(_ done: @escaping () -> Void) {
        guard isSignedIn, let rows = readLegacyRows() else { return done() }
        var remaining = rows[...]
        var failed = false
        func next() {
            guard let row = remaining.popFirst() else {
                if !failed { self.retireLegacyDB() }
                return done()
            }
            createDocument(id: "local-\(self.session?.uid ?? "")-\(row.id)", fields: row.fields) { error in
                if error != nil { failed = true }
                next()
            }
        }
        next()
    }

    private func retireLegacyDB() {
        let stamp = isoDay()
        for suffix in ["", "-wal", "-shm"] {
            let from = URL(fileURLWithPath: legacyDB.path + suffix)
            guard FileManager.default.fileExists(atPath: from.path) else { continue }
            let to = dir.appendingPathComponent("notes-imported-\(stamp).db\(suffix)")
            try? FileManager.default.moveItem(at: from, to: to)
        }
    }
}

enum CloudError: Error {
    case notSignedIn
    case network(String)

    var message: String {
        switch self {
        case .notSignedIn: return "Your Google account couldn’t be confirmed. Please try again."
        case .network(let detail): return "Couldn’t reach Firebase (\(detail))."
        }
    }
}
